    'about.storyP2': 'We refuse artificial colorings, synthetic stabilizers, and industrialized shortcuts. Every single layer of puff pastry is hand-laminated over three days using single-origin Normandy butter. Every fruit filling is simmered in copper pots from farm-picked mountain cherries and wild strawberries.',
